166	// ---- 形态：草稿保留原草稿且当前版本为空；已更正记录保留标识、当前版本与完整版本链 ----
167	//
168	// 同一患者的两次就诊各放一条草稿与一条已更正记录，诊断、医嘱两个类别都覆盖；
169	// 查询只返回该次就诊的记录，其他就诊（含同一患者）的内容不能混入，草稿也不
170	// 能被表现为已生效版本。
171	
172	func TestEncounterRecordsDraftAndCorrectedShapes(t *testing.T) {
173		s, _ := newTestStore(t)
174		pid, e1 := setupPatientEncounter(t, s)
175		e2, err := s.AddEncounter(doc, pid, time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC))
176		if err != nil {
177			t.Fatal(err)
178		}
179	
180		// 就诊一：草稿诊断 + 已更正医嘱。
181		draftDx := mustCreateDraft(t, s, pid, e1, Diagnosis, "草稿诊断内容")
182		corrOrd := mustCreateDraft(t, s, pid, e1, Order, "医嘱第 1 版内容")
183		ov1 := mustActivate(t, s, corrOrd)
184		ov2 := mustCorrect(t, s, corrOrd, 1, "医嘱第 2 版内容", "医嘱更正原因")
185	
186		// 就诊二：已更正诊断 + 草稿医嘱（保证两个类别在两种形态下都出现）。
187		corrDx := mustCreateDraft(t, s, pid, e2.ID, Diagnosis, "诊断第 1 版内容")
188		dv1 := mustActivate(t, s, corrDx)
189		dv2 := mustCorrect(t, s, corrDx, 1, "诊断第 2 版内容", "诊断更正原因")
190		draftOrd := mustCreateDraft(t, s, pid, e2.ID, Order, "草稿医嘱内容")
191	
192		got1, err := s.EncounterRecords(doc, pid, e1)
193		if err != nil {
194			t.Fatal(err)
195		}
196		if len(got1) != 2 {
197			t.Fatalf("encounter 1 should have exactly 2 records, got %d (%v)", len(got1), recordIDList(got1))
198		}
199		m1 := historiesByID(got1)
200	
201		// 草稿：保留原草稿内容，当前版本为空，没有任何历史版本，不得表现为已生效。
202		d, ok := m1[draftDx]
203		if !ok {
204			t.Fatalf("draft diagnosis missing from encounter view: %v", recordIDList(got1))
205		}
206		if d.Record.ID != draftDx {
207			t.Fatalf("draft record id changed: %q", d.Record.ID)
208		}
209		if !d.HasDraft || d.DraftContent != "草稿诊断内容" {
210			t.Fatalf("draft content not preserved: HasDraft=%v Content=%q", d.HasDraft, d.DraftContent)
211		}
212		if d.CurrentVersion != nil {
213			t.Fatalf("draft must not be presented as effective, got current version %+v", d.CurrentVersion)
214		}
215		if d.Record.CurrentVersionID != "" || len(d.Record.Versions) != 0 || len(d.Versions) != 0 {
216			t.Fatalf("draft must carry no versions, got id list %v history %+v", d.Record.Versions, d.Versions)
217		}
218	
219		// 已生效并更正过的记录：原记录标识、当前版本、旧到新的全部版本、
220		// 各次更正原因与上一版本关系都保留。
221		c, ok := m1[corrOrd]
222		if !ok {
223			t.Fatalf("corrected order missing from encounter view: %v", recordIDList(got1))
224		}
225		if c.Record.ID != corrOrd {
226			t.Fatalf("corrected record lost its original id: %q", c.Record.ID)
227		}
228		if c.CurrentVersion == nil || c.CurrentVersion.ID != ov2.ID || c.CurrentVersion.Number != 2 ||
229			c.CurrentVersion.Content != "医嘱第 2 版内容" {
230			t.Fatalf("current version wrong: %+v", c.CurrentVersion)
231		}
232		if want := []ID{ov1.ID, ov2.ID}; !reflect.DeepEqual(c.Record.Versions, want) {
233			t.Fatalf("version id list = %v, want %v", c.Record.Versions, want)
234		}
235		if len(c.Versions) != 2 {
236			t.Fatalf("full history should keep 2 versions, got %d", len(c.Versions))
237		}
238		if c.Versions[0].Number != 1 || c.Versions[0].Content != "医嘱第 1 版内容" ||
239			c.Versions[0].PrevID != "" || c.Versions[0].Reason != "" {
240			t.Fatalf("v1 not preserved: %+v", c.Versions[0])
241		}
242		if c.Versions[1].ID != ov2.ID || c.Versions[1].Number != 2 ||
243			c.Versions[1].Content != "医嘱第 2 版内容" ||
244			c.Versions[1].PrevID != ov1.ID || c.Versions[1].Reason != "医嘱更正原因" {
245			t.Fatalf("v2 chain/reason wrong: %+v", c.Versions[1])
246		}
247		if c.Versions[0].Number > c.Versions[1].Number {
248			t.Fatal("history must be ordered old to new")
249		}
250	
251		// 查询只返回该次就诊：同一患者其他就诊的草稿与版本均不能混入。
252		for _, h := range got1 {
253			if h.Record.EncounterID != e1 {
254				t.Fatalf("record from another encounter leaked in: %+v", h.Record)
255			}
256			if h.Record.ID == corrDx || h.Record.ID == draftOrd {
257				t.Fatalf("encounter 2 record %q leaked into encounter 1 view", h.Record.ID)
258			}
259		}
260	
261		// 就诊二的查询同样自成一域，且诊断类别的版本链同样完整。
262		got2, err := s.EncounterRecords(doc, pid, e2.ID)
263		if err != nil {
264			t.Fatal(err)
265		}
266		if len(got2) != 2 {
267			t.Fatalf("encounter 2 should have exactly 2 records, got %d (%v)", len(got2), recordIDList(got2))
268		}
269		m2 := historiesByID(got2)
270		for _, h := range got2 {
271			if h.Record.EncounterID != e2.ID {
272				t.Fatalf("encounter 1 record leaked into encounter 2 view: %+v", h.Record)
273			}
274		}
275		cd := m2[corrDx]
276		if cd.CurrentVersion == nil || cd.CurrentVersion.ID != dv2.ID || cd.CurrentVersion.Number != 2 {
277			t.Fatalf("corrected diagnosis current version wrong: %+v", cd.CurrentVersion)
278		}
279		if len(cd.Versions) != 2 ||
280			cd.Versions[0].ID != dv1.ID || cd.Versions[0].PrevID != "" ||
281			cd.Versions[1].ID != dv2.ID || cd.Versions[1].PrevID != dv1.ID ||
282			cd.Versions[1].Reason != "诊断更正原因" {
283			t.Fatalf("corrected diagnosis chain wrong: %+v", cd.Versions)
284		}
285		do2 := m2[draftOrd]
286		if do2.CurrentVersion != nil || !do2.HasDraft || do2.DraftContent != "草稿医嘱内容" {
287			t.Fatalf("draft order shape wrong: %+v", do2)
288		}
289	}
