431	// ---- 正常更正后：新查询显示真实新版本；先前结果停留在查询时状态 ----
432	//
433	// 更正判断只以正式记录的当前版本号为准，不依据调用方本地修改过的查询结果；
434	// 使用已过期的正式版本号仍返回 ErrConflict，完整历史与审计保持原样。
435	
436	func TestEncounterRecordsCorrectionUsesOfficialVersion(t *testing.T) {
437		s, _ := newTestStore(t)
438		pid, e1 := setupPatientEncounter(t, s)
439		rid := mustCreateDraft(t, s, pid, e1, Diagnosis, "诊断第 1 版内容")
440		v1 := mustActivate(t, s, rid)
441		v2 := mustCorrect(t, s, rid, 1, "诊断第 2 版内容", "第一次更正原因")
442	
443		// 更正前取得、此后不在本地改动的结果。
444		frozen, err := s.EncounterRecords(doc, pid, e1)
445		if err != nil {
446			t.Fatal(err)
447		}
448	
449		// 另一份结果被调用方任意修改（抬高版本号、换掉记录标识）。
450		local, err := s.EncounterRecords(doc, pid, e1)
451		if err != nil {
452			t.Fatal(err)
453		}
454		tamperHistory(&local[0])
455	
456		auditBeforeCorrection := mustAudit(t, s, pid)
457	
458		// 以正式当前版本号 2 更正成功：证明判断不看本地被改成 999 的那份结果。
459		v3, err := s.CorrectRecord(doc, rid, 2, "诊断第 3 版内容", "第二次更正原因")
460		if err != nil {
461			t.Fatalf("correction based on official current version should succeed: %v", err)
462		}
463		if v3.Number != 3 {
464			t.Fatalf("new version number = %d, want official current + 1 = 3", v3.Number)
465		}
466		if v3.PrevID != v2.ID || v3.Reason != "第二次更正原因" || v3.Content != "诊断第 3 版内容" {
467			t.Fatalf("new version chain/reason/content wrong: %+v", v3)
468		}
469	
470		// 新查询显示真实生成的新版本与完整链路。
471		fresh, err := s.EncounterRecords(doc, pid, e1)
472		if err != nil {
473			t.Fatal(err)
474		}
475		if len(fresh) != 1 {
476			t.Fatalf("unexpected records: %v", recordIDList(fresh))
477		}
478		h := fresh[0]
479		if h.Record.ID != rid {
480			t.Fatalf("record id changed: %q", h.Record.ID)
481		}
482		if h.CurrentVersion == nil || h.CurrentVersion.ID != v3.ID || h.CurrentVersion.Number != 3 ||
483			h.CurrentVersion.Content != "诊断第 3 版内容" ||
484			h.CurrentVersion.PrevID != v2.ID || h.CurrentVersion.Reason != "第二次更正原因" {
485			t.Fatalf("fresh query current version wrong: %+v", h.CurrentVersion)
486		}
487		if want := []ID{v1.ID, v2.ID, v3.ID}; !reflect.DeepEqual(h.Record.Versions, want) {
488			t.Fatalf("version id list = %v, want %v", h.Record.Versions, want)
489		}
490		if len(h.Versions) != 3 {
491			t.Fatalf("full history should keep all 3 versions, got %d", len(h.Versions))
492		}
493		nums := []int{h.Versions[0].Number, h.Versions[1].Number, h.Versions[2].Number}
494		if want := []int{1, 2, 3}; !reflect.DeepEqual(nums, want) {
495			t.Fatalf("version order = %v, want %v", nums, want)
496		}
497		if h.Versions[0].PrevID != "" || h.Versions[1].PrevID != v1.ID || h.Versions[2].PrevID != v2.ID {
498			t.Fatalf("prev-version chain broken: %q %q %q",
499				h.Versions[0].PrevID, h.Versions[1].PrevID, h.Versions[2].PrevID)
500		}
501		if h.Versions[1].Reason != "第一次更正原因" || h.Versions[2].Reason != "第二次更正原因" {
502			t.Fatalf("correction reasons not preserved: %+v", h.Versions)
503		}
504	
505		// 此前取得且未在本地改动的结果继续反映查询时状态，不自动变成新版本。
506		fb := historiesByID(frozen)[rid]
507		if fb.CurrentVersion == nil || fb.CurrentVersion.Number != 2 ||
508			fb.CurrentVersion.ID != v2.ID || fb.CurrentVersion.Content != "诊断第 2 版内容" {
509			t.Fatalf("earlier result must stay at its query-time snapshot: %+v", fb.CurrentVersion)
510		}
511		if len(fb.Versions) != 2 {
512			t.Fatalf("earlier result must not gain the new version, got %d versions", len(fb.Versions))
513		}
514		for _, v := range fb.Record.Versions {
515			if v == v3.ID {
516				t.Fatal("new version leaked into the earlier query result")
517			}
518		}
519		// 被本地改过的那份结果同样保持调用方留下的样子，不被正式状态覆盖或回写。
520		if local[0].CurrentVersion == nil || local[0].CurrentVersion.Number != 999 {
521			t.Fatalf("locally edited result changed unexpectedly: %+v", local[0].CurrentVersion)
522		}
523	
524		// 使用已过期的正式版本号：ErrConflict，完整历史与审计保持原样。
525		wantFresh := snapshotHistories(fresh)
526		if _, err := s.CorrectRecord(doc, rid, 2, "凭过期版本号的抢占更正", "并发更正"); !errors.Is(err, ErrConflict) {
527			t.Fatalf("stale official version err = %v, want ErrConflict", err)
528		}
529		if _, err := s.CorrectRecord(doc, rid, 1, "凭更旧版本号的抢占更正", "并发更正"); !errors.Is(err, ErrConflict) {
530			t.Fatalf("older official version err = %v, want ErrConflict", err)
531		}
532		afterConflict, err := s.EncounterRecords(doc, pid, e1)
533		if err != nil {
534			t.Fatal(err)
535		}
536		assertHistoriesMatches(t, afterConflict, wantFresh, "history after stale corrections")
537	
538		events := mustAudit(t, s, pid)
539		if len(events) != len(auditBeforeCorrection)+1 {
540			t.Fatalf("successful correction should add exactly one audit event, got delta %d",
541				len(events)-len(auditBeforeCorrection))
542		}
543		counts := auditActions(events)
544		if counts[ActionActivated] != 1 || counts[ActionCorrected] != 2 {
545			t.Fatalf("audit counts wrong after conflicts: %v", counts)
546		}
547	}
548	
549	// ---- 权限：接收方不能调用内部查询；拒绝时不携带草稿或历史内容 ----
550	
551	func TestEncounterRecordsReceiverDeniedWithoutContent(t *testing.T) {
552		s, clk := newTestStore(t)
553		pid, e1 := setupPatientEncounter(t, s)
554		rid := mustCreateDraft(t, s, pid, e1, Diagnosis, "仅供内部查看的草稿内容")
555		mustActivate(t, s, rid)
556		mustCorrect(t, s, rid, 1, "仅供内部查看的更正内容", "仅供内部查看的更正原因")
557	
558		// 无授权：拒绝，结果为 nil，不夹带草稿或历史。
559		got, err := s.EncounterRecords(rcv, pid, e1)
560		if !errors.Is(err, ErrAccessDenied) {
561			t.Fatalf("receiver internal query err = %v, want ErrAccessDenied", err)
562		}
563		if got != nil {
564			t.Fatalf("denied query must carry no draft or history, got %+v", got)
565		}
566	
567		// 即使持有覆盖该就诊诊断的有效接收授权，内部查询入口仍不对接收方开放。
568		if _, err := s.Grant(doc, pid, rcv.ID,
569			[]Scope{{EncounterID: e1, Category: Diagnosis}},
570			clk.t.Add(-time.Hour), clk.t.Add(time.Hour)); err != nil {
571			t.Fatalf("grant: %v", err)
572		}
573		got2, err2 := s.EncounterRecords(rcv, pid, e1)
574		if !errors.Is(err2, ErrAccessDenied) {
575			t.Fatalf("receiver with grant err = %v, want ErrAccessDenied", err2)
576		}
577		if got2 != nil {
578			t.Fatalf("denied query must carry no draft or history, got %+v", got2)
579		}
580	}
